buttons.className:
{`flex-1 py-2 mobile:min-h-11 rounded-lg text-sm mobile:text-mb-compact font-semibold transition-colors ${
              mode === 'direct'
                ? 'bg-white text-[#5F0080] shadow-sm'
                : 'text-[#6F6F6F] hover:text-[#1F1F1F]'
            }`}

{`flex-1 py-2 mobile:min-h-11 rounded-lg text-sm mobile:text-mb-compact font-semibold transition-colors ${
              mode === 'group'
                ? 'bg-white text-[#5F0080] shadow-sm'
                : 'text-[#6F6F6F] hover:text-[#1F1F1F]'
            }`}

{`min-h-[44px] rounded-full px-4 text-sm font-semibold ${
              filter === item.key
                ? 'border border-[#5F0080] bg-[#F5EDFC] text-[#5F0080]'
                : 'border border-[#ECE6F0] bg-white text-[#6F6F6F]'
            }`}

{`bg-transparent border-0 px-[18px] py-[10px] font-sans text-[15px] cursor-pointer ${
                active === label ? 'font-bold text-purple-900' : 'font-medium text-gray-800'
              }`}

{`w-full text-left bg-white border border-[#EFEFEF] rounded-2xl p-4 hover:shadow-sm transition-all ${
        !notification.is_read ? 'border-l-[3px] border-l-[#5F0080]' : ''
      }`}

{[
        'rounded px-2 py-1 text-[11px] font-medium transition-colors',
        active
          ? 'bg-[#5F0080] text-white'
          : 'bg-[#F5EDFC] text-[#6F6F6F] hover:bg-[#EBDEF7] hover:text-[#5F0080]',
      ].join(' ')}

{[
        'rounded px-2 py-1 text-[11px] font-medium transition-colors',
        active
          ? 'bg-[#5F0080] text-white'
          : 'bg-[#F5EDFC] text-[#6F6F6F] hover:bg-[#EBDEF7] hover:text-[#5F0080]',
      ].join(' ')}

{[
                'rounded px-2 py-1 text-[11px] font-medium transition-colors',
                rangeSec === r.sec
                  ? 'bg-[#5F0080] text-white'
                  : 'bg-[#F5EDFC] text-[#6F6F6F] hover:bg-[#EBDEF7] hover:text-[#5F0080]',
              ].join(' ')}

{`px-4 py-2 text-sm font-medium transition-colors ${
              activeTab === id
                ? 'border-b-2 border-[#5F0080] text-[#5F0080]'
                : 'text-[#6F6F6F] hover:text-[#1F1F1F]'
            }`}

{`mobile:min-h-11 mobile:min-w-11 flex w-full gap-3 rounded-xl border px-4 py-2.5 text-left ${meta.color} ${
              onSeek ? 'cursor-pointer transition hover:opacity-80' : 'cursor-default'
            }`}

{`flex items-center justify-between gap-3 rounded-xl px-4 py-4 text-left transition ${
              warn
                ? 'bg-[#F2212133] text-[#F22121B2]'
                : 'bg-[#F2F3F8] text-[#1F1F1F]'
            } ${
              selected
                ? 'outline outline-2 outline-[#5F0080] outline-offset-0'
                : ''
            }`}

{`flex flex-col gap-3 rounded-2xl border p-4 text-left transition hover:shadow-md ${
        alert
          ? 'border-[#F5C2C0] bg-[#FDECEC]'
          : row.raise_hand
            ? 'border-[#F5D48B] bg-[#FDF6E5]'
            : 'border-[#EFEFEF] bg-white'
      } ${selected ? 'outline outline-2 outline-[#5F0080] outline-offset-0' : ''}`}

{`w-full px-4 py-3 text-left hover:bg-[#F8FAFC] ${
                    index === highlightIndex ? 'bg-[#F5EDFC]' : ''
                  }`}

{`px-4 py-2 rounded-xl text-[15px] font-medium text-white disabled:opacity-50 ${
                      modal.action === 'suspend' ? 'bg-[#EF4444]' : 'bg-[#10B981]'
                    }`}

{`px-4 py-2 rounded-xl text-[15px] font-medium text-white disabled:opacity-50 ${
                  modal.action === 'suspend' || modal.action === 'delete' ? 'bg-[#EF4444]' : 'bg-[#10B981]'
                }`}

{`min-w-0 flex-1 text-left flex items-center gap-3 px-4 md:px-5 py-3.5 md:py-4 transition-colors ${
                          isActive ? 'bg-[#F5EDFC]' : 'hover:bg-[#F8F8FB] active:bg-[#F0F0F5]'
                        }`}

{`min-h-[40px] min-w-[76px] rounded-[10px] px-3 text-sm ${
                  view === mode ? 'bg-[#F5EDFC] font-bold text-[#5F0080]' : 'text-[#6F6F6F]'
                }`}

{`min-h-[40px] min-w-[56px] rounded-[10px] px-3 text-sm ${
                      days === p.days ? 'bg-[#F5EDFC] font-bold text-[#5F0080]' : 'text-[#6F6F6F]'
                    }`}

{`min-h-[44px] rounded-full border px-3 text-sm ${
                      types.includes(t)
                        ? 'border-[#5F0080] bg-[#F5EDFC] font-bold text-[#5F0080]'
                        : 'border-[#DDDEE7] text-[#6F6F6F]'
                    }`}

{`rounded-xl px-4 py-2.5 text-[15px] font-semibold text-white disabled:opacity-50 ${
              isSuspend ? 'bg-[#B3261E] hover:bg-[#991B1B]' : 'bg-[#1F8A5B] hover:bg-[#065F46]'
            }`}

{`px-4 py-2.5 text-[13px] font-semibold transition-colors ${
              tab === key
                ? 'border-b-2 border-[#5F0080] text-[#5F0080]'
                : 'text-[#6F6F6F] hover:text-[#1F1F1F]'
            }`}

{`rounded-lg border px-2.5 py-1.5 text-[12px] font-semibold ${
                                  status === 'suspended'
                                    ? 'border-[#A7D9C4] text-[#1F8A5B] hover:bg-[#E6F8F3]'
                                    : 'border-[#F0B8B4] text-[#B3261E] hover:bg-[#FDECEC]'
                                }`}

{`flex-1 h-11 rounded-xl border text-sm font-medium transition-colors ${
                        gender === opt.value
                          ? 'border-brand-primary bg-brand-primary/10 text-brand-primary'
                          : 'border-border-default text-ink-secondary hover:bg-surface-elevated'
                      }`}

{`mobile:min-h-11 mobile:min-w-11 block w-full text-left bg-white border border-[#EFEFEF] rounded-2xl p-4 transition-all ${
        r.id ? 'hover:border-[#5F0080]/30 hover:shadow-sm' : 'bg-[#FDFDFD]'
      }`}

{`mobile:min-h-11 mobile:min-w-11 h-10 px-3.5 text-[13px] mobile:text-mb-label font-semibold transition-colors ${
                    statusFilter === value
                      ? value === 'failed'
                        ? 'bg-[#C62828] text-white'
                        : 'bg-[#5F0080] text-white'
                      : 'text-[#6F6F6F] hover:bg-[#F8FAFC]'
                  }`}

{`rounded-lg min-h-[44px] px-4 py-2.5 text-[12px] font-medium transition ${
                monitorView === v.key
                  ? 'bg-[#5F0080] text-white'
                  : 'bg-[#F2F3F8] text-[#6F6F6F] hover:text-[#1F1F1F]'
              }`}
